const express = require("express");
const db = require("../db");

const router = express.Router();

router.post("/", async (req, res) => {
  const idempotencyKey = req.get("Idempotency-Key");

  if (idempotencyKey) {
    const existing = await db.query(
      "SELECT result FROM idempotency_keys WHERE account_id = $1 AND key = $2",
      [req.user.accountId, idempotencyKey]
    );
    if (existing.length) {
      return res.status(201).json(JSON.parse(existing[0].result));
    }
  }

  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  if (idempotencyKey) {
    await db.write(
      "INSERT INTO idempotency_keys (account_id, key, result) VALUES ($1, $2, $3)",
      [req.user.accountId, idempotencyKey, JSON.stringify(row)]
    );
  }

  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row.length) {
    return res.status(404).end();
  }
  res.json(row);
});

module.exports = router;

