      method: req.method,
      path: req.path,
      userId: req.user?.id,
      accountId: req.user?.accountId,
      status: res.statusCode,
      durationMs: duration,
    });
    return originalJson(data);
  };

  res.end = function(...args) {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      userId: req.user?.id,
      accountId: req.user?.accountId,
      status: res.statusCode,
      durationMs: duration,
    });
    return originalEnd(...args);
  };

  next();
});
```

**For errors:** Wrap route handlers to catch exceptions and log them with stack traces before re-throwing.

**Key benefits:**
- Single point of instrumentation
- Captures all requests uniformly
- Can tie requests to users (post-auth)
- Structured logging (JSON format) works well with log aggregators
- No changes needed to individual route handlers

**Considerations:**
- Skip logging sensitive query params/body fields
- Use a proper logger library (winston, pino) for production instead of `console.log`
- Log to stderr or a file, not stdout if stdout is used for API responses

**Problem:** If a client retries the POST (due to timeout/network error), the same order gets inserted multiple times.

**Solution: Idempotency keys** (standard pattern used by Stripe, AWS, etc.)

The client includes a unique `Idempotency-Key` header on each request. The server:

1. Checks if it's seen this key before
2. If yes → return the cached response (same order)
3. If no → process the request, cache the result, return it

**Implementation:**

Add an `idempotency_keys` table to track requests:

```sql
CREATE TABLE idempotency_keys (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  account_id INT NOT NULL,
  idempotency_key TEXT NOT NULL,
  request_body JSONB,
  response_body JSONB,
  created_at TIMESTAMP DEFAULT now(),
  UNIQUE(account_id, idempotency_key)
);
```

Then in the POST handler:

```javascript
router.post("/", async (req, res) => {
  const idempotencyKey = req.headers['idempotency-key'];

  if (!idempotencyKey) {
    return res.status(400).json({ error: "Idempotency-Key header required" });
  }

  // Check if we've already processed this key
  const cached = await db.query(
    "SELECT response_body FROM idempotency_keys WHERE account_id = $1 AND idempotency_key = $2",
    [req.user.accountId, idempotencyKey]
  );

  if (cached.length) {
    return res.status(201).json(cached[0].response_body);
  }

  // Process the order
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );

  // Store the idempotency key and response
  await db.write(
    "INSERT INTO idempotency_keys (account_id, idempotency_key, response_body) VALUES ($1, $2, $3)",
    [req.user.accountId, idempotencyKey, JSON.stringify(row)]
  );

  res.status(201).json(row);
});
```

**Key points:**

- Scope by `account_id` so one account's idempotency key doesn't collide with another's
- The `write()` call should probably be wrapped in a transaction with the idempotency insert to avoid race conditions
- Optional: add expiration (TTL) to old idempotency keys to save space
- Client must preserve the same `Idempotency-Key` across retries for the same logical request

