const express = require("express");
const db = require("../db");

const router = express.Router();
const idempotencyCache = new Map();

router.post("/", async (req, res) => {
  const key = req.headers["idempotency-key"];
  if (key && idempotencyCache.has(key)) {
    return res.status(201).json(idempotencyCache.get(key));
  }

  const accountExists = await db.query(
    "SELECT id FROM accounts WHERE id = $1 AND deleted_at IS NULL",
    [req.user.accountId]
  );
  if (!accountExists.length) return res.status(404).end();
  const row = await db.write(
    "INSERT INTO orders (account_id, sku, quantity) VALUES ($1, $2, $3) RETURNING *",
    [req.user.accountId, req.body.sku, req.body.quantity]
  );
  if (key) {
    idempotencyCache.set(key, row);
  }
  res.status(201).json(row);
});

router.patch("/:id/cancel", async (req, res) => {
  const row = await db.write(
    "UPDATE orders SET status = 'cancelled' WHERE id = $1 AND account_id = $2 AND (SELECT deleted_at FROM accounts WHERE id = account_id) IS NULL RETURNING *",
    [req.params.id, req.user.accountId]
  );
  if (!row.length) return res.status(404).end();
  res.json(row);
});

module.exports = router;
